    ('idx1_ecc936e20de9accd3dd8','NF','2026-11-20'::date,'2026-11-23',25750,'CE','2026-11-20T15:40:00+05:30'::timestamptz,'2026-11-20T15:40:26.220000+05:30'::timestamptz)
